-- PurchaseIn stock txns =====
INSERT Inv_StockTransaction(TransactionNo,TransactionType,ProductId,WarehouseId,Qty,BalanceQty,RefType,RefId,RefNo,Operator,Remark,CreateTime,CreateBy) SELECT CONCAT('PIN-TXN-',pid.Id),1,pid.ProductId,pi.WarehouseId,pid.Qty,ISNULL((SELECT TOP 1 BalanceQty FROM Inv_StockTransaction WHERE ProductId=pid.ProductId AND WarehouseId=pi.WarehouseId ORDER BY CreateTime DESC,Id DESC),0)+pid.Qty,'PurchaseIn',pi.Id,pi.InNo,pi.Operator,'采购入库自动流水',DATEADD(day,0,pi.InDate),pi.CreateBy FROM Pur_PurchaseInDetail pid JOIN Pur_PurchaseIn pi ON pid.PurchaseInId=pi.Id WHERE pi.IsDeleted=0;

-- PurchaseReturn stock txns (out) =====
INSERT Inv_StockTransaction(TransactionNo,TransactionType,ProductId,WarehouseId,Qty,BalanceQty,RefType,RefId,RefNo,Operator,Remark,CreateTime,CreateBy) SELECT CONCAT('PRT-TXN-',prd.Id),2,prd.ProductId,pr.WarehouseId,-prd.Qty,ISNULL((SELECT TOP 1 BalanceQty FROM Inv_StockTransaction WHERE ProductId=prd.ProductId AND WarehouseId=pr.WarehouseId ORDER BY CreateTime DESC,Id DESC),0)-prd.Qty,'PurchaseReturn',pr.Id,pr.ReturnNo,pr.Operator,'采购退货出库自动流水',DATEADD(day,0,pr.ReturnDate),pr.CreateBy FROM Pur_PurchaseReturnDetail prd JOIN Pur_PurchaseReturn pr ON prd.PurchaseReturnId=pr.Id WHERE pr.IsDeleted=0;

-- SaleOut stock txns (out) =====
INSERT Inv_StockTransaction(TransactionNo,TransactionType,ProductId,WarehouseId,Qty,BalanceQty,RefType,RefId,RefNo,Operator,Remark,CreateTime,CreateBy) SELECT CONCAT('SHP-TXN-',sod.Id),3,sod.ProductId,sod.WarehouseId,-sod.Qty,ISNULL((SELECT TOP 1 BalanceQty FROM Inv_StockTransaction WHERE ProductId=sod.ProductId AND WarehouseId=sod.WarehouseId ORDER BY CreateTime DESC,Id DESC),0)-sod.Qty,'SaleOut',so.Id,so.OutNo,so.Operator,'销售出库自动流水',DATEADD(day,0,so.OutTime),so.CreateBy FROM Sale_SaleOutDetail sod JOIN Sale_SaleOut so ON sod.SaleOutId=so.Id WHERE so.IsDeleted=0;

-- SaleReturn stock txns (in) =====
INSERT Inv_StockTransaction(TransactionNo,TransactionType,ProductId,WarehouseId,Qty,BalanceQty,RefType,RefId,RefNo,Operator,Remark,CreateTime,CreateBy) SELECT CONCAT('SLR-TXN-',srd.Id),4,srd.ProductId,srd.WarehouseId,srd.Qty,ISNULL((SELECT TOP 1 BalanceQty FROM Inv_StockTransaction WHERE ProductId=srd.ProductId AND WarehouseId=srd.WarehouseId ORDER BY CreateTime DESC,Id DESC),0)+srd.Qty,'SaleReturn',sr.Id,sr.ReturnNo,sr.Operator,'销售退货入库自动流水',DATEADD(day,0,sr.ReturnDate),sr.CreateBy FROM Sale_ReturnDetail srd JOIN Sale_Return sr ON srd.SaleReturnId=sr.Id WHERE sr.IsDeleted=0;

-- StockTransfer out =====
INSERT Inv_StockTransaction(TransactionNo,TransactionType,ProductId,WarehouseId,Qty,BalanceQty,RefType,RefId,RefNo,Operator,Remark,CreateTime,CreateBy) SELECT CONCAT('TRN-OUT-',std.Id),6,std.ProductId,st.FromWarehouseId,-std.Qty,ISNULL((SELECT TOP 1 BalanceQty FROM Inv_StockTransaction WHERE ProductId=std.ProductId AND WarehouseId=st.FromWarehouseId ORDER BY CreateTime DESC,Id DESC),0)-std.Qty,'StockTransfer',st.Id,st.TransferNo,st.Operator,'调拨出库自动流水',DATEADD(day,0,st.TransferDate),st.CreateBy FROM Inv_StockTransferDetail std JOIN Inv_StockTransfer st ON std.TransferId=st.Id WHERE st.Status=3 AND st.IsDeleted=0;

-- StockTransfer in =====
INSERT Inv_StockTransaction(TransactionNo,TransactionType,ProductId,WarehouseId,Qty,BalanceQty,RefType,RefId,RefNo,Operator,Remark,CreateTime,CreateBy) SELECT CONCAT('TRN-IN-',std.Id),5,std.ProductId,st.ToWarehouseId,std.Qty,ISNULL((SELECT TOP 1 BalanceQty FROM Inv_StockTransaction WHERE ProductId=std.ProductId AND WarehouseId=st.ToWarehouseId ORDER BY CreateTime DESC,Id DESC),0)+std.Qty,'StockTransfer',st.Id,st.TransferNo,st.Operator,'调拨入库自动流水',DATEADD(day,0,st.TransferDate),st.CreateBy FROM Inv_StockTransferDetail std JOIN Inv_StockTransfer st ON std.TransferId=st.Id WHERE st.Status=3 AND st.IsDeleted=0;

-- StockCheck gain/loss =====
INSERT Inv_StockTransaction(TransactionNo,TransactionType,ProductId,WarehouseId,Qty,BalanceQty,RefType,RefId,RefNo,Operator,Remark,CreateTime,CreateBy) SELECT CONCAT('CHK-ADJ-',scd.Id),CASE WHEN scd.DiffQty>=0 THEN 7 ELSE 8 END,scd.ProductId,sc.WarehouseId,scd.DiffQty,ISNULL((SELECT TOP 1 BalanceQty FROM Inv_StockTransaction WHERE ProductId=scd.ProductId AND WarehouseId=sc.WarehouseId ORDER BY CreateTime DESC,Id DESC),0)+scd.DiffQty,'StockCheck',sc.Id,sc.CheckNo,sc.Operator,'盘点调整自动流水',DATEADD(day,0,sc.CheckDate),sc.CreateBy FROM Inv_StockCheckDetail scd JOIN Inv_StockCheck sc ON scd.StockCheckId=sc.Id WHERE sc.Status=3 AND scd.DiffQty!=0 AND sc.IsDeleted=0;

-- RepairPart usage =====
INSERT Inv_StockTransaction(TransactionNo,TransactionType,ProductId,WarehouseId,Qty,BalanceQty,RefType,RefId,RefNo,Operator,Remark,CreateTime,CreateBy) SELECT CONCAT('REP-USE-',rp.Id),10,rp.ProductId,rp.WarehouseId,-rp.Qty,ISNULL((SELECT TOP 1 BalanceQty FROM Inv_StockTransaction WHERE ProductId=rp.ProductId AND WarehouseId=rp.WarehouseId ORDER BY CreateTime DESC,Id DESC),0)-rp.Qty,'RepairOrder',rp.RepairOrderId,ro.OrderNo,N'maxiang','维修领用自动流水',DATEADD(day,0,ro.CreateTime),ro.CreateBy FROM Maint_RepairPart rp JOIN Maint_RepairOrder ro ON rp.RepairOrderId=ro.Id;
GO


