-- Update Base_ProductStock =====
DELETE FROM Base_ProductStock;
INSERT Base_ProductStock(ProductId,WarehouseId,Quantity,LockQty,IsDeleted,CreateTime,CreateBy) SELECT ProductId,WarehouseId,SUM(Qty) AS Quantity,0,0,MAX(CreateTime),N'system' FROM Inv_StockTransaction GROUP BY ProductId,WarehouseId HAVING SUM(Qty)>0;


-- ===== Self-Check SQL =====
SELECT 'PO Status' AS Info, Status, COUNT(*) AS Cnt FROM Pur_PurchaseOrder WHERE IsDeleted=0 GROUP BY Status ORDER BY Status;
SELECT 'SO Status' AS Info, Status, COUNT(*) AS Cnt FROM Sale_SaleOrder WHERE IsDeleted=0 GROUP BY Status ORDER BY Status;
SELECT 'Repair Status' AS Info, Status, COUNT(*) AS Cnt FROM Maint_RepairOrder WHERE IsDeleted=0 GROUP BY Status ORDER BY Status;
SELECT 'Counts' AS Info, 'PO' AS Module, COUNT(*) AS Cnt FROM Pur_PurchaseOrder WHERE IsDeleted=0 UNION ALL SELECT 'Counts','SO',COUNT(*) FROM Sale_SaleOrder WHERE IsDeleted=0 UNION ALL SELECT 'Counts','Pin',COUNT(*) FROM Pur_PurchaseIn WHERE IsDeleted=0 UNION ALL SELECT 'Counts','PRet',COUNT(*) FROM Pur_PurchaseReturn WHERE IsDeleted=0 UNION ALL SELECT 'Counts','SOut',COUNT(*) FROM Sale_SaleOut WHERE IsDeleted=0 UNION ALL SELECT 'Counts','SRet',COUNT(*) FROM Sale_Return WHERE IsDeleted=0 UNION ALL SELECT 'Counts','STrans',COUNT(*) FROM Inv_StockTransfer WHERE IsDeleted=0 UNION ALL SELECT 'Counts','SCheck',COUNT(*) FROM Inv_StockCheck WHERE IsDeleted=0 UNION ALL SELECT 'Counts','Alert',COUNT(*) FROM Inv_StockAlert WHERE IsResolved=0 UNION ALL SELECT 'Counts','Device',COUNT(*) FROM Maint_DeviceArchive WHERE IsDeleted=0 UNION ALL SELECT 'Counts','Repair',COUNT(*) FROM Maint_RepairOrder WHERE IsDeleted=0 UNION ALL SELECT 'Counts','Plan',COUNT(*) FROM Maint_MaintenancePlan WHERE IsDeleted=0 UNION ALL SELECT 'Counts','Log',COUNT(*) FROM Sys_OperationLog UNION ALL SELECT 'Counts','Txn',COUNT(*) FROM Inv_StockTransaction;
SELECT 'Pending-PO' AS Info, COUNT(*) AS Cnt FROM Pur_PurchaseOrder WHERE Status=1 AND IsDeleted=0 UNION ALL SELECT 'Pending-SO',COUNT(*) FROM Sale_SaleOrder WHERE Status=1 AND IsDeleted=0 UNION ALL SELECT 'Pending-STrans',COUNT(*) FROM Inv_StockTransfer WHERE Status=1 AND IsDeleted=0 UNION ALL SELECT 'Pending-Repair',COUNT(*) FROM Maint_RepairOrder WHERE Status=0 AND IsDeleted=0;

